WITH with_windows AS (SELECT id, customer_id, store_id, order_date, status, channel, amount, discount, shipping_fee, PERCENT_RANK() OVER (PARTITION BY store_id ORDER BY shipping_fee DESC NULLS FIRST) AS shipping_fee_percent_rank, AVG(amount) OVER (PARTITION BY channel) AS channel_avg_amount, AVG(discount) OVER w_part AS discount_avg_2, AVG(shipping_fee) OVER w_running AS shipping_fee_avg_2, ROW_NUMBER() OVER (ORDER BY amount ASC, id ASC) AS event_seq FROM orders WINDOW w_part AS (ORDER BY order_date ASC, id ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), w_running AS (PARTITION BY channel, customer_id ORDER BY order_date ASC, id ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)) SELECT DATE_TRUNC('MONTH', order_date) AS activity_month, MIN(discount_avg_2) AS min_discount_avg_2, AVG(amount) AS avg_amount, SUM(discount) FILTER (WHERE status = 'RETURNED') AS returned_total_discount, COUNT(*) FILTER (WHERE channel = 'partner') AS partner_rows FROM with_windows GROUP BY DATE_TRUNC('MONTH', order_date);
